fn check_if_last_char_is_a_letter(txt: &str) -> bool {
    // Get an iterator over the chars of the string
    let mut chars = txt.chars();

    // Early return false if empty
    if chars.next().is_none() {
        return false;
    }

    // We want to efficiently (and safely) access the last char and the one before it (if any).
    // Use a double-ended iterator to peek last and second-to-last chars:
    // 1. Check the last char
    // 2. If last char is ASCII alphabetic, then check if either txt is length 1 OR
    //    the previous character is a space.

    let last_char = txt.chars().rev().next().unwrap();

    // Check if last_char is ASCII alphabetic
    if !last_char.is_ascii_alphabetic() {
        return false;
    }

    // Count the total number of chars so we know length
    let len = txt.chars().count();

    if len == 1 {
        // single character string that is ASCII alphabetic -> true
        return true;
    }

    // If length > 1, check the char immediately before the last one:
    let mut rev_chars = txt.chars().rev();
    rev_chars.next(); // discard last char
    let penultimate_char = rev_chars.next().unwrap();

    penultimate_char == ' '
}